var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var sb = new System.Text.StringBuilder();
sb.Append("activeScene=" + scene.name + " path=" + scene.path + " rootCount=" + scene.rootCount).Append("\n");
GameObject found = null;
foreach (var root in scene.GetRootGameObjects())
{
    foreach (var t in root.GetComponentsInChildren<Transform>(true))
    {
        if (t.name == "Slot 1") { found = t.gameObject; break; }
    }
    if (found != null) break;
}
if (found == null) return sb.ToString() + "Slot 1 NOT FOUND in active scene";
sb.Append("found.scene=" + found.scene.name + " path=" + found.scene.path).Append("\n");
var outer = PrefabUtility.GetOutermostPrefabInstanceRoot(found);
sb.Append("outermostPrefabRoot=" + (outer == null ? "(none)" : outer.name)).Append("\n");
var src = PrefabUtility.GetCorrespondingObjectFromSource(found);
sb.Append("correspondingSource=" + (src == null ? "(none)" : AssetDatabase.GetAssetPath(src))).Append("\n");
sb.Append("isPartOfPrefabInstance=" + PrefabUtility.IsPartOfPrefabInstance(found)).Append("\n");
sb.Append("isPartOfPrefabAsset=" + PrefabUtility.IsPartOfPrefabAsset(found)).Append("\n");
return sb.ToString();
